"""Order controller: request decoding and response mapping only.

Business decisions (such as discount eligibility) belong to the application
service, and the controller never imports a repository.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from orders.application.order_service import OrderNotFound, OrderService
from orders.domain import LineItem, Order, OrderSummary


@dataclass(frozen=True)
class Response:
    status: int
    body: dict[str, Any]


class InvalidRequest(ValueError):
    pass


def _decode_items(raw: Any) -> list[LineItem]:
    if not isinstance(raw, list) or not raw:
        raise InvalidRequest("items must be a non-empty list")
    items = []
    for entry in raw:
        if not isinstance(entry, dict):
            raise InvalidRequest("each item must be an object")
        sku = entry.get("sku")
        quantity = entry.get("quantity")
        price = entry.get("unit_price_cents")
        if not isinstance(sku, str) or not sku:
            raise InvalidRequest("sku must be a non-empty string")
        if type(quantity) is not int or quantity < 1:
            raise InvalidRequest("quantity must be a positive integer")
        if type(price) is not int or price < 0:
            raise InvalidRequest("unit_price_cents must be a non-negative integer")
        items.append(LineItem(sku, quantity, price))
    return items


def _order_body(order: Order) -> dict[str, Any]:
    return {
        "order_id": order.order_id,
        "customer_id": order.customer_id,
        "status": order.status,
        "items": [
            {"sku": i.sku, "quantity": i.quantity, "unit_price_cents": i.unit_price_cents}
            for i in order.items
        ],
    }


def _summary_body(summary: OrderSummary) -> dict[str, Any]:
    return {
        **_order_body(summary.order),
        "subtotal_cents": summary.subtotal_cents,
        "discount_cents": summary.discount_cents,
        "total_cents": summary.total_cents,
    }


class OrderController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_create(self, request: dict[str, Any]) -> Response:
        try:
            customer_id = request.get("customer_id")
            if not isinstance(customer_id, str) or not customer_id:
                raise InvalidRequest("customer_id must be a non-empty string")
            items = _decode_items(request.get("items"))
        except InvalidRequest as exc:
            return Response(400, {"error": str(exc)})
        order = self._service.place_order(customer_id, items)
        return Response(201, _order_body(order))

    def handle_get(self, order_id: str) -> Response:
        try:
            summary = self._service.get_order_summary(order_id)
        except OrderNotFound:
            return Response(404, {"error": "order not found"})
        return Response(200, _summary_body(summary))

    def handle_list_for_customer(self, customer_id: str) -> Response:
        orders = self._service.list_for_customer(customer_id)
        return Response(200, {"orders": [_order_body(o) for o in orders]})

"""In-memory order repository. Stands in for a database; no I/O."""

from __future__ import annotations

from orders.domain import Order


class InMemoryOrderRepository:
    def __init__(self) -> None:
        self._orders: dict[str, Order] = {}
        self._next_id = 1

    def next_id(self) -> str:
        order_id = f"ord-{self._next_id:04d}"
        self._next_id += 1
        return order_id

    def add(self, order: Order) -> None:
        self._orders[order.order_id] = order

    def get(self, order_id: str) -> Order | None:
        return self._orders.get(order_id)

    def list_for_customer(self, customer_id: str) -> list[Order]:
        # dicts preserve insertion order, so this is creation order.
        return [o for o in self._orders.values() if o.customer_id == customer_id]

"""Plain domain data shared by every layer. Money is integer cents."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class LineItem:
    sku: str
    quantity: int
    unit_price_cents: int

    @property
    def line_total_cents(self) -> int:
        return self.quantity * self.unit_price_cents


@dataclass(frozen=True)
class Order:
    order_id: str
    customer_id: str
    items: tuple[LineItem, ...]
    status: str = "placed"

    @property
    def subtotal_cents(self) -> int:
        return sum(item.line_total_cents for item in self.items)


@dataclass(frozen=True)
class OrderSummary:
    order: Order
    subtotal_cents: int
    discount_cents: int
    total_cents: int

"""Application-service tests: the service owns business policy and repository access."""

import pytest
from hypothesis import given
from hypothesis import strategies as st

from orders.application.order_service import (
    DISCOUNT_RATE_PERCENT,
    DISCOUNT_THRESHOLD_CENTS,
    OrderNotFound,
    OrderService,
    discount_for,
)
from orders.domain import LineItem
from orders.infrastructure.repository import InMemoryOrderRepository


def make_service():
    return OrderService(InMemoryOrderRepository())


def test_place_order_persists_through_the_repository():
    repository = InMemoryOrderRepository()
    service = OrderService(repository)

    order = service.place_order("cust-1", [LineItem("A", 1, 100)])

    assert repository.get(order.order_id) == order


def test_get_order_raises_for_unknown_ids():
    with pytest.raises(OrderNotFound):
        make_service().get_order("missing")


def test_summary_applies_the_discount_policy():
    service = make_service()
    order = service.place_order("cust-1", [LineItem("A", 2, 6_000)])

    summary = service.get_order_summary(order.order_id)

    assert summary.subtotal_cents == 12_000
    assert summary.discount_cents == 1_200
    assert summary.total_cents == 10_800


class TestProperties:
    @given(st.integers(min_value=0, max_value=10**12))
    def test_discount_is_bounded_and_only_applies_at_or_above_threshold(self, subtotal):
        discount = discount_for(subtotal)

        assert 0 <= discount <= subtotal
        if subtotal < DISCOUNT_THRESHOLD_CENTS:
            assert discount == 0
        else:
            assert discount == subtotal * DISCOUNT_RATE_PERCENT // 100

