    return build_app()


def create(controller, customer_id="cust-1", items=None):
    if items is None:
        items = [{"sku": "BOOK", "quantity": 2, "unit_price_cents": 1500}]
    return controller.handle_create({"customer_id": customer_id, "items": items})


